<?php require '../config/bootstrap.php';auth();if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: ../my-products.php');exit;}verify_token();$id=(int)($_POST['id']??0);$s=$pdo->prepare('SELECT gambar_produk FROM produk WHERE id=? AND user_id=?');$s->execute([$id,me()['id']]);$p=$s->fetch();if($p){$pdo->prepare('DELETE FROM produk WHERE id=? AND user_id=?')->execute([$id,me()['id']]);del_img($p['gambar_produk']);flash('Produk dihapus');}else flash('Produk tidak ditemukan','error');header('Location: ../my-products.php');exit;